insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-22','verbeterd','Relaties','VvE''s staan niet langer tussen de opdrachtgevers',
   'Ruim honderd VvE''s stonden in het relatieoverzicht alsof zij ons de opdracht geven, terwijl de beheerder dat doet en de VvE alleen de factuur krijgt. Die VvE''s zijn nu het factuuradres onder hun beheerder en verdwijnen uit het overzicht en uit de keuzelijst bij een nieuwe aanvraag. Zoeken op de naam van de VvE werkt gewoon: je krijgt dan de beheerder te zien, met vermelding via welk factuuradres hij gevonden is.'),
  ('2026-09-22','verbeterd','Dossiers','Het factuuradres van een dossier loopt mee naar Bouw7',
   'Van vierentachtig dossiers stond de VvE als opdrachtgever ingevuld; die zijn omgezet naar de beheerder, met de VvE als factuuradres. Kies je voortaan een ander factuuradres op een dossier, dan wordt dat ook in Bouw7 bijgewerkt. Daarmee staat in beide systemen dezelfde partij op de factuur.');
